    exception.expect(IOException.class);
    exception.expectMessage("EOF");
    Span span = TraceUtil.createSpan(testName.getMethodName());
    try (Scope ignored = span.makeCurrent()) {
        BlockIOUtils.preadWithExtra(bb, in, position, necessaryLen, extraLen);
        span.setStatus(StatusCode.OK);
    } catch (IOException e) {
        TraceUtil.setError(span, e);
        throw e;
    } finally {
        span.end();
        TEST_UTIL.waitFor(TimeUnit.MINUTES.toMillis(1), new MatcherPredicate<Iterable<SpanData>>(otelRule::getSpans, hasItem(allOf(hasName(testName.getMethodName()), hasEnded()))));
        assertThat(otelRule.getSpans(), hasItems(allOf(hasName(testName.getMethodName()), hasEvents(hasItem(allOf(EventMatchers.hasName("BlockIOUtils.preadWithExtra"), hasAttributes(AttributesMatchers.isEmpty())))))));
    }
}

